/* ========================= */

function getEvolutionChain(pokemon){

  const map = new Map(POKEMON.map(p => [p.id, p]));

  let root = pokemon;

  while(root.evo && root.evo.prev){
    root = map.get(root.evo.prev);
  }

  let chain = [];

  function walk(p){
    if(!p) return;

    chain.push(p);

    if(p.evo && p.evo.next){

      if(Array.isArray(p.evo.next)){
        p.evo.next.forEach(id=>{
          let next = map.get(id);
          if(next) chain.push(next);
        });
      } else {
        walk(map.get(p.evo.next));
      }

    }
  }

  walk(root);
  return chain;
}
